package com.bank.finaldemo.service;

import com.bank.finaldemo.dto.FinalReport;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import java.math.BigDecimal;
import java.util.*;
import java.util.stream.Collectors;

@Service
@Slf4j
public class FinalDemoService {

    record Trade(String id, BigDecimal amount) {}

    private final List<Trade> trades = List.of(
        new Trade("TRD-001", new BigDecimal("245050")),
        new Trade("TRD-002", new BigDecimal("176000")),
        new Trade("TRD-003", new BigDecimal("330150")),
        new Trade("TRD-004", new BigDecimal("33664")),
        new Trade("TRD-005", new BigDecimal("222037"))
    );

    public FinalReport demonstrate() {
        List<String> explanations = new ArrayList<>();

        // ═══ 1. EXPLICITLY FINAL — keyword present ═══
        final BigDecimal thresholdExplicit = new BigDecimal("200000");
        List<String> explicitResults = trades.stream()
            .filter(t -> t.amount().compareTo(thresholdExplicit) > 0)
            .map(Trade::id)
            .toList();
        // thresholdExplicit = new BigDecimal("300000");  // COMPILE ERROR at THIS line
        log.info("Explicit final: threshold={}, results={}", thresholdExplicit, explicitResults);

        // ═══ 2. EFFECTIVELY FINAL — no keyword, never reassigned ═══
        BigDecimal thresholdEffective = new BigDecimal("200000");
        // NO reassignment of thresholdEffective anywhere → effectively final
        List<String> effectiveResults = trades.stream()
            .filter(t -> t.amount().compareTo(thresholdEffective) > 0)
            .map(Trade::id)
            .toList();
        log.info("Effectively final: threshold={}, results={}", thresholdEffective, effectiveResults);

        // ═══ 3. PROOF: identical results ═══
        boolean identical = explicitResults.equals(effectiveResults);
        explanations.add("Both produce identical results: " + identical);
        explanations.add("Both capture the VALUE 200000 — same bytecode");

        // ═══ 4. WHEN FINAL ADDS VALUE — method parameter documentation ═══
        BigDecimal fee = calculateFee(trades.get(0), new BigDecimal("0.001"));
        explanations.add("final on method params: documents intent, catches reassignment early");

        // ═══ 5. WHEN EFFECTIVELY FINAL IS FINE — simple local ═══
        String accountId = "SAV2001";  // obviously never reassigned
        long count = trades.stream().filter(t -> t.id().startsWith("TRD")).count();
        explanations.add("effectively final for simple locals: 'final String accountId' adds noise");

        // ═══ 6. HISTORY: Java 7 required explicit final for anonymous classes ═══
        explanations.add("Java 7: anonymous inner classes required explicit 'final'");
        explanations.add("Java 8: lambdas accept effectively final — 'final' became optional");
        explanations.add("No behavioral difference — only documentation/style difference");

        return new FinalReport(explicitResults, effectiveResults, identical, explanations);
    }

    // ═══ FINAL on method parameters — documents contract ═══
    private BigDecimal calculateFee(final Trade trade, final BigDecimal rate) {
        // trade = new Trade("X", BigDecimal.ZERO);  // COMPILE ERROR — final!
        // rate = BigDecimal.ONE;                     // COMPILE ERROR — final!
        return trade.amount().multiply(rate);
    }
}
```

