package com.bank.finaldemo.service;

import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import java.util.*;
import static org.assertj.core.api.Assertions.*;

class EffectivelyFinalVsFinalTest {

    @Test
    void bothProduceSameResultInLambda() {
        final int explicitFinal = 10;
        int effectivelyFinal = 10;  // never reassigned

        long explicit = List.of(5, 15, 25).stream().filter(n -> n > explicitFinal).count();
        long effective = List.of(5, 15, 25).stream().filter(n -> n > effectivelyFinal).count();

        assertThat(explicit).isEqualTo(effective);  // IDENTICAL!
    }

    @Test
    void effectivelyFinalMeansNeverReassigned() {
        String name = "Rajesh";  // never reassigned → effectively final
        // name = "Priya";       // If uncommented → NOT effectively final → lambda breaks

        Optional<String> result = Optional.of("Hello")
            .map(s -> s + " " + name);  // captures effectively final 'name'

        assertThat(result).contains("Hello Rajesh");
    }

    @Test
    void finalMethodParameterDocumentsIntent() {
        // final on parameter prevents reassignment inside the method
        assertThat(addFee(new BigDecimal("100"), new BigDecimal("0.1")))
            .isEqualByComparingTo("110");
    }

    private BigDecimal addFee(final BigDecimal amount, final BigDecimal rate) {
        // amount = BigDecimal.ZERO;  // COMPILE ERROR — final parameter!
        return amount.add(amount.multiply(rate));
    }

    @Test
    void capturedInLoopMustBeEffectivelyFinal() {
        List<Runnable> tasks = new ArrayList<>();
        for (int i = 0; i < 3; i++) {
            final int captured = i;  // explicit final — captures current loop value
            tasks.add(() -> System.out.println("Task " + captured));
        }
        // Without final/effectively final: 'i' is reassigned each iteration → can't capture!
        // Each iteration creates a NEW variable 'captured' that is final → safe.
        assertThat(tasks).hasSize(3);
    }

    @Test
    void java8RelaxedFromExplicitToEffective() {
        // Java 7 anonymous class: required EXPLICIT final
        // final String msg = "Hello";
        // Runnable r = new Runnable() { public void run() { System.out.println(msg); } };

        // Java 8 lambda: accepts effectively final
        String msg = "Hello";  // no final keyword — effectively final is enough
        Runnable r = () -> System.out.println(msg);  // compiles in Java 8+
        assertThat(r).isNotNull();
    }
}
